mapper.select:
SELECT m.id member_id,m.name,m.phone,u.email,m.birth_date,m.gender,COALESCE((SELECT mp.name FROM member_memberships mm JOIN membership_products mp ON mp.id=mm.product_id WHERE mm.member_id=m.id AND mm.status='ACTIVE' AND mm.end_date>=CURRENT_DATE ORDER BY mm.end_date LIMIT 1),'활성 회원권 없음') active_membership,
COALESCE((SELECT SUM(mm.remaining_pt_sessions) FROM member_memberships mm JOIN membership_products mp ON mp.id=mm.product_id WHERE mm.member_id=m.id AND mm.status='ACTIVE' AND mp.product_type IN ('PT','COMBINED')),0) remaining_pt_sessions
FROM trainers t JOIN trainer_assignments ta ON ta.trainer_id=t.id AND ta.status='ACTIVE' JOIN members m ON m.id=ta.member_id JOIN users u ON u.id=m.user_id WHERE t.user_id=#{userId} AND m.id=#{memberId}
